const uint8_t *nui_glyph_find(uint16_t cp)
{
    for (int i = 0; i < (int)(sizeof(g_tab) / sizeof(g_tab[0])); i++) {
        if (g_tab[i].cp == cp) return g_tab[i].bm;
    }
    return NULL;
}

int nui_glyph_w(void) { return NUI_GW; }
int nui_glyph_h(void) { return NUI_GH; }
